using Astronomy.MediaFactory.Core.AstronomyDomain.Entities; using Astronomy.MediaFactory.Core.AstronomyDomain.Families; using Astronomy.MediaFactory.Core.AstronomyDomain.Localization; using Astronomy.MediaFactory.Core.AstronomyDomain.Relationships; using Astronomy.MediaFactory.Core.AstronomyDomain.Sources;
namespace Astronomy.MediaFactory.Core.AstronomyDomain.Validation;
public enum DomainValidationSeverity { Information, Warning, Error }
public sealed record DomainValidationIssue(string Code,string Message,DomainValidationSeverity Severity,string? Path=null,string? EntityId=null,string? FamilyId=null,string? Recommendation=null);
public sealed record DomainValidationResult(IReadOnlyList<DomainValidationIssue> Issues){ public bool IsValid=>Issues.All(i=>i.Severity!=DomainValidationSeverity.Error); public int ErrorCount=>Issues.Count(i=>i.Severity==DomainValidationSeverity.Error); public int WarningCount=>Issues.Count(i=>i.Severity==DomainValidationSeverity.Warning); public static DomainValidationResult Success {get;}=new([]); public static DomainValidationResult From(params DomainValidationIssue[] issues)=>new(issues.OrderBy(i=>i.Code,StringComparer.Ordinal).ThenBy(i=>i.Path,StringComparer.Ordinal).ToArray());}
public interface IAstronomyDomainValidator{DomainValidationResult ValidateEntity(IAstronomyDomainEntity entity);DomainValidationResult ValidateFamily(IAstronomyDomainFamily family);DomainValidationResult ValidateRelationship(AstronomyRelationship relationship);DomainValidationResult ValidateLocalization(AstronomyLocalizedContent localization);DomainValidationResult ValidateSource(AstronomySourceReference source);} 
